import 'package:equatable/equatable.dart';

/// 🔱 STRATEGIC OPTIMIZATION (Blueprint v1.0 - Document 58/59)
/// Represents the optimal preparation plan generated by the Chief Strategist.
class OptimizationNode extends Equatable {
  final String userId;
  final String realmId;
  
  final int optimalDailyMinutes;
  final Map<String, int> optimalSubjectMix; // Subject -> Minutes
  final Map<String, String> recommendedCampaigns; // Subject -> Campaign ID
  
  final double estimatedProbabilityGain;
  final String strategyNarrative; // Human-readable explanation of why this plan is optimal
  
  final DateTime optimizedAt;

  const OptimizationNode({
    required this.userId,
    required this.realmId,
    required this.optimalDailyMinutes,
    required this.optimalSubjectMix,
    required this.recommendedCampaigns,
    required this.estimatedProbabilityGain,
    required this.strategyNarrative,
    required this.optimizedAt,
  });

  Map<String, dynamic> toMap() {
    return {
      'userId': userId,
      'realmId': realmId,
      'optimalDailyMinutes': optimalDailyMinutes,
      'optimalSubjectMix': optimalSubjectMix,
      'recommendedCampaigns': recommendedCampaigns,
      'estimatedProbabilityGain': estimatedProbabilityGain,
      'strategyNarrative': strategyNarrative,
      'optimizedAt': optimizedAt.toIso8601String(),
    };
  }

  factory OptimizationNode.fromMap(Map<String, dynamic> map) {
    return OptimizationNode(
      userId: map['userId'] ?? '',
      realmId: map['realmId'] ?? '',
      optimalDailyMinutes: map['optimalDailyMinutes'] ?? 0,
      optimalSubjectMix: Map<String, int>.from(map['optimalSubjectMix'] ?? {}),
      recommendedCampaigns: Map<String, String>.from(map['recommendedCampaigns'] ?? {}),
      estimatedProbabilityGain: (map['estimatedProbabilityGain'] ?? 0.0).toDouble(),
      strategyNarrative: map['strategyNarrative'] ?? '',
      optimizedAt: DateTime.parse(map['optimizedAt'] ?? DateTime.now().toIso8601String()),
    );
  }

  @override
  List<Object?> get props => [userId, realmId, optimalDailyMinutes, optimizedAt];
}
